// --- THE SERVICE (Heavy Business Logic) ---
class PaymentService {
  static async processRefund(userId, amount) {
    // 1. Business Rule: Check if amount is valid
    if (amount <= 0) throw new Error("Invalid amount");

    // 2. Call external APIs (Stripe)
    console.log(`Contacting Stripe to refund $${amount}...`);

    // 3. Database Updates
    console.log(`Updating User ${userId} balance in database...`);

    return "Refund Complete";
  }
}

// --- THE CONTROLLER (Skinny & HTTP Focused) ---
const handleRefundRoute = async (req, res) => {
  try {
    const { userId, amount } = req.body; // Extract HTTP data

    // Pass to Service
    const result = await PaymentService.processRefund(userId, amount);

    res.status(200).json({ message: result }); // Send HTTP response
  } catch (error) {
    res.status(400).json({ error: error.message });
  }
};

console.log("The Service Layer makes your core business logic completely independent of Express.js.");
